<?php
if(!defined('ABSPATH'))exit;
function dgs_catalog_subject_icon($subject){$path='';if(strpos($subject,'ریاضی')!==false)$path='M4 2h16v20H4zM7 6h10M7 10h3M14 10h3M8.5 8.5v3M7 15l3 3M10 15l-3 3M14 15h3M14 18h3';elseif(strpos($subject,'فیزیک')!==false)$path='M12 10a2 2 0 1 0 0 4 2 2 0 0 0 0-4M3 12c0-5 18-5 18 0s-18 5-18 0M7 4c4-2 14 12 10 16S3 6 7 4M17 4c-4-2-14 12-10 16s14-14 10-16';elseif(strpos($subject,'شیمی')!==false)$path='M9 2h6M10 2v7L4 20c0 1 1 2 2 2h12c1 0 2-1 2-2L14 9V2M7 16h10M10 18h1M14 20h1';elseif(strpos($subject,'زیست')!==false)$path='M20 3C3 2 1 13 8 18S22 14 20 3M3 22L17 7M9 16v-5M13 12h5';return $path?'<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="'.$path.'"/></svg>':dgs_portal_icon('study');}
function dgs_catalog_get($key,$default=''){return isset($_GET[$key])&&is_string($_GET[$key])?sanitize_text_field(wp_unslash($_GET[$key])):$default;}
function dgs_catalog_grade($value){$value=dgs_edu_digits((string)$value);foreach(array(10,11,12) as $g)if(in_array($value,array((string)$g,dgs_edu_grade_label($g),'پایه '.dgs_edu_grade_label($g)),true))return (string)$g;return '';}
function dgs_catalog_grades($value){return array_values(array_intersect(array_map('trim',explode(',',str_replace('،',',',dgs_edu_digits((string)$value)))),array('10','11','12')));}
function dgs_catalog_select($name,$label,$options,$selected=''){$out='<label>'.esc_html($label).'<select name="'.esc_attr($name).'">';foreach($options as $key=>$text)$out.='<option value="'.esc_attr($key).'" '.selected((string)$selected,(string)$key,false).'>'.esc_html($text).'</option>';return $out.'</select></label>';}
function dgs_catalog_pagination($page,$pages,$key,$url){if($pages<2)return '';$out='<nav class="dc-pagination" aria-label="صفحه‌بندی">';foreach(array_unique(array_filter(array(1,$page-1,$page,$page+1,$pages),function($p)use($pages){return $p>0&&$p<=$pages;})) as $p)$out.='<a '.($page===$p?'aria-current="page"':'').' href="'.esc_url(add_query_arg($key,$p,$url)).'">'.esc_html(dgs_fa_digits($p)).'</a>';return $out.'</nav>';}
function dgs_catalog_heading($title,$sub,$icon){return '<header class="dc-heading"><h1>'.dgs_portal_icon($icon).esc_html($title).'</h1><p>'.esc_html($sub).'</p></header>';}
function dgs_teacher_directory(){
 $subject=dgs_catalog_get('teacher_subject');$grade=dgs_catalog_grade(dgs_catalog_get('teacher_grade'));$search=dgs_catalog_get('teacher_search');$page=max(1,min(1000,absint(dgs_catalog_get('teacher_page','1'))));
 $meta=array('relation'=>'AND',array('relation'=>'OR',array('key'=>'_dgs_group','value'=>'teacher'),array('key'=>'_dgs_group','compare'=>'NOT EXISTS')));if($subject!=='')$meta[]=array('key'=>'_dgs_specialty','value'=>$subject);if($grade)$meta[]=array('key'=>'_dgs_grades','value'=>$grade,'compare'=>'LIKE');
 $query=new WP_Query(array('post_type'=>'dgs_teacher','post_status'=>'publish','posts_per_page'=>8,'paged'=>$page,'s'=>$search,'meta_query'=>$meta,'orderby'=>array('menu_order'=>'ASC','title'=>'ASC')));$subjects=array(''=>'همه دروس');foreach(get_posts(array('post_type'=>'dgs_teacher','post_status'=>'publish','numberposts'=>-1,'fields'=>'ids')) as $id){if(get_post_meta($id,'_dgs_group',true)==='staff')continue;$v=get_post_meta($id,'_dgs_specialty',true);if($v)$subjects[$v]=$v;}
 $out='<div class="dc-page dc-teachers"><section class="dc-teacher-banner"><div><h1>اساتید دانشگران</h1><p>با تیم تخصصی و مجرب اساتید مدرسه دانشگران آشنا شوید.</p></div><img src="'.esc_url(dgs_hero_image()).'" alt="نمای مدرسه" loading="lazy"></section><form class="dc-filter" method="get" action="'.esc_url(dgs_page_url('teachers')).'">'.dgs_catalog_select('teacher_subject','رشته / درس',$subjects,$subject).dgs_catalog_select('teacher_grade','پایه تحصیلی',array(''=>'همه پایه‌ها',10=>'دهم',11=>'یازدهم',12=>'دوازدهم'),$grade).'<label>جست‌وجو<input name="teacher_search" value="'.esc_attr($search).'" placeholder="نام استاد یا موضوع تدریس…" maxlength="100"></label><button class="dg-btn">'.dgs_portal_icon('search').' جست‌وجو</button></form><div class="dc-teacher-grid">';
 foreach($query->posts as $post){$years=get_post_meta($post->ID,'_dgs_teaching_years',true);$out.='<article class="dc-teacher-card"><a class="dc-teacher-photo" href="'.esc_url(get_permalink($post)).'">'.dgs_avatar($post->ID,'medium').'</a><h2>'.esc_html($post->post_title).'</h2><span class="dc-tag">'.dgs_catalog_subject_icon(get_post_meta($post->ID,'_dgs_specialty',true)).esc_html(get_post_meta($post->ID,'_dgs_specialty',true)?:'مدرس مدرسه').'</span><p>'.dgs_portal_icon('timetable').' '.($years!==''?'سابقه تدریس: '.esc_html(dgs_fa_digits($years)).' سال':'سابقه تدریس ثبت نشده است.').'</p><a class="dg-btn" href="'.esc_url(get_permalink($post)).'">'.dgs_portal_icon('file').' مشاهده رزومه</a></article>';}
 if(!$query->posts)$out.=dgs_empty('استادی با این مشخصات منتشر نشده است.');$out.='</div><div class="dc-list-bottom"><small>نمایش '.esc_html(dgs_fa_digits(count($query->posts))).' مورد از '.esc_html(dgs_fa_digits($query->found_posts)).' استاد</small>'.dgs_catalog_pagination($page,(int)$query->max_num_pages,'teacher_page',remove_query_arg('teacher_page')).'</div></div>';return $out;
}
function dgs_catalog_lines($value){$lines=array_filter(array_map('trim',preg_split('/\r?\n/',(string)$value)));if(!$lines)return '<p class="dc-empty">هنوز ثبت نشده است.</p>';$out='<ul class="dc-lines">';foreach($lines as $line)$out.='<li>'.esc_html($line).'</li>';return $out.'</ul>';}
function dgs_catalog_teacher_post($class){$uid=absint(get_post_meta($class,'_dgs_teacher_user',true));$id=$uid?(int)get_user_meta($uid,'_dgs_teacher_post',true):0;return $id&&get_post_type($id)==='dgs_teacher'&&get_post_status($id)==='publish'?$id:0;}
function dgs_catalog_teacher_name($class){$id=dgs_catalog_teacher_post($class);return $id?get_the_title($id):get_post_meta($class,'_dgs_teacher_name',true);}
function dgs_catalog_classes($teacher=0){$args=array('post_type'=>'dgs_class','post_status'=>'publish','numberposts'=>200,'orderby'=>'title','order'=>'ASC');if($teacher){$uid=(int)get_post_meta($teacher,'_dgs_user_id',true);$args['meta_query']=$uid?array(array('key'=>'_dgs_teacher_user','value'=>(string)$uid)):array(array('key'=>'_dgs_teacher_name','value'=>get_the_title($teacher)));}return get_posts($args);}
function dgs_teacher_profile($id){
 if(get_post_type($id)!=='dgs_teacher'||get_post_status($id)!=='publish')return dgs_empty('رزومه منتشر نشده است.');$specialty=get_post_meta($id,'_dgs_specialty',true);$grades=dgs_catalog_grades(get_post_meta($id,'_dgs_grades',true));$video=get_post_meta($id,'_dgs_video',true);$classes=dgs_catalog_classes($id);
 $out='<div class="dc-page dc-profile"><div class="dc-breadcrumb"><a href="'.esc_url(dgs_page_url('teachers')).'">اساتید</a> ‹ رزومه استاد</div>'.dgs_catalog_heading('رزومه استاد','','users').'<section class="dc-profile-hero"><div class="dc-profile-person"><div class="dc-profile-photo">'.dgs_avatar($id,'medium_large').'</div><div><h2>'.esc_html(get_the_title($id)).'</h2><span class="dc-tag">'.dgs_portal_icon('education').esc_html($specialty).'</span><p>'.($grades?'مدرس پایه‌های '.esc_html(implode('، ',array_map('dgs_edu_grade_label',$grades))):'پایه‌های تدریس هنوز ثبت نشده است.').'</p></div></div><div class="dc-profile-video">';if($video&&preg_match('/\.(mp4|webm)$/i',(string)wp_parse_url($video,PHP_URL_PATH)))$out.=wp_video_shortcode(array('src'=>esc_url($video),'poster'=>has_post_thumbnail($id)?get_the_post_thumbnail_url($id,'large'):''));else $out.='<div class="dc-video-empty">'.dgs_portal_icon('file').'<p>ویدئوی معرفی هنوز ثبت نشده است.</p></div>';$out.='</div></section><div class="dc-profile-grid"><section class="dc-card"><h2>'.dgs_portal_icon('users').' درباره استاد</h2><div>'.(get_post_field('post_content',$id)?wpautop(wp_kses_post(get_post_field('post_content',$id))):'<p>معرفی استاد هنوز ثبت نشده است.</p>').'</div></section><section class="dc-card"><h2>'.dgs_portal_icon('classes').' تدریس در پایه‌ها و درس‌ها</h2>';if($grades){foreach($grades as $g)$out.='<div class="dc-grade-row"><strong>'.esc_html($specialty).'</strong><span class="dc-tag">پایه '.esc_html(dgs_edu_grade_label($g)).'</span></div>';}else $out.='<p>پایه‌های تدریس ثبت نشده است.</p>';
 $out.='</section><section class="dc-card"><h2>'.dgs_portal_icon('education').' سوابق تحصیلی</h2>'.dgs_catalog_lines(get_post_meta($id,'_dgs_education',true)).'</section><section class="dc-card"><h2>'.dgs_portal_icon('file').' سوابق و تجربه‌های آموزشی</h2>'.dgs_catalog_lines(get_post_meta($id,'_dgs_experience',true)).'</section></div>';if(get_post_meta($id,'_dgs_skills',true))$out.='<section class="dc-card"><h2>'.dgs_portal_icon('grades').' مهارت‌ها</h2>'.dgs_catalog_lines(get_post_meta($id,'_dgs_skills',true)).'</section>';
 $out.='<section class="dc-card"><h2>'.dgs_portal_icon('grades').' کلاس‌های تقویتی و ارتقای مهارت</h2>';foreach($classes as $class){$out.='<div class="dc-profile-class"><div><strong>'.esc_html($class->post_title).'</strong><small>'.esc_html(get_post_meta($class->ID,'_dgs_schedule',true)).'</small></div><span>'.dgs_portal_icon('pin').esc_html(get_post_meta($class->ID,'_dgs_venue',true)?:'محل برگزاری اعلام می‌شود').'</span><span>'.dgs_portal_icon('timetable').' شروع: '.esc_html(get_post_meta($class->ID,'_dgs_start_date',true)?:'اعلام می‌شود').'</span><a class="dg-btn" href="'.esc_url(add_query_arg('academy_id',$class->ID,dgs_public_url('class'))).'">پیش‌ثبت‌نام '.dgs_portal_icon('arrow').'</a></div>';}
 if(!$classes)$out.='<p>کلاس تقویتی منتشرشده‌ای برای این استاد ثبت نشده است.</p>';return $out.'</section></div>';
}
function dgs_catalog_days($id){return array_values(array_intersect(array_filter(array_map('trim',explode(',',str_replace('،',',',dgs_edu_digits((string)get_post_meta($id,'_dgs_days',true))))),function($v){return $v!=='';}),array('0','1','2','3','4','5')));}
function dgs_catalog_day_names(){return array('شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه');}
function dgs_catalog_schedule($posts){$rows=array();$days=dgs_catalog_day_names();foreach($posts as $p){$start=get_post_meta($p->ID,'_dgs_time_start',true);$end=get_post_meta($p->ID,'_dgs_time_end',true);$ds=dgs_catalog_days($p->ID);if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/D',$start)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/D',$end)||$end<=$start||!$ds)continue;$slot=$start.'–'.$end;foreach($ds as $day)$rows[$slot][$day][]=$p;}ksort($rows);if(!$rows)return '<p class="dc-empty">برنامه ساختاریافته هفتگی هنوز ثبت نشده است؛ زمان اعلام‌شده هر کلاس در کارت آن نمایش داده می‌شود.</p>';
 $out='<div class="dc-table-wrap"><table class="dc-table"><thead><tr><th>ساعت</th>';foreach($days as $day)$out.='<th>'.esc_html($day).'</th>';$out.='</tr></thead><tbody>';foreach($rows as $slot=>$cells){$out.='<tr><th dir="ltr">'.esc_html(dgs_fa_digits($slot)).'</th>';foreach(array_keys($days) as $day){$out.='<td>';foreach($cells[$day]??array() as $class)$out.='<a href="'.esc_url(get_permalink($class)).'">'.esc_html($class->post_title).'</a><br>';$out.=empty($cells[$day])?'—':'';$out.='</td>';}$out.='</tr>';}return $out.'</tbody></table></div>';
}
function dgs_catalog_academy(){
 $all=dgs_catalog_classes();$grade=dgs_catalog_grade(dgs_catalog_get('academy_grade'));$day=dgs_catalog_get('academy_day');$subject=dgs_catalog_get('academy_subject');$subjects=array(''=>'همه دروس');foreach($all as $p){$v=get_post_meta($p->ID,'_dgs_subject',true);if($v)$subjects[$v]=$v;}$posts=array_filter($all,function($p)use($grade,$day,$subject){return (!$grade||dgs_catalog_grade(get_post_meta($p->ID,'_dgs_grade',true))===$grade)&&($day===''||in_array($day,dgs_catalog_days($p->ID),true))&&($subject===''||get_post_meta($p->ID,'_dgs_subject',true)===$subject);});
 $out='<div class="dc-page dc-academy">'.dgs_catalog_heading('آموزشگاه و کلاس‌های تقویتی','برنامه کلاس‌های تقویتی و مرور دروس پایه‌های دهم، یازدهم و دوازدهم','education').'<section class="dc-academy-intro"><div><h2>تقویت یادگیری، آمادگی برای موفقیت بزرگ‌تر</h2><p>کلاس‌های تقویتی مدرسه برای تعمیق یادگیری و مرور هدفمند دروس برگزار می‌شوند. برنامه و مدرس هر کلاس را بررسی کنید و درخواست پیش‌ثبت‌نام خود را ارسال کنید.</p></div><div class="dc-academy-art" role="img" aria-label="کتاب‌ها و ابزار یادگیری"></div></section><section class="dc-card"><h2>'.dgs_portal_icon('search').' جست‌وجو و فیلتر کلاس‌ها</h2><form class="dc-filter" method="get" action="'.esc_url(dgs_page_url('academy')).'">'.dgs_catalog_select('academy_grade','پایه تحصیلی',array(''=>'همه پایه‌ها',10=>'دهم',11=>'یازدهم',12=>'دوازدهم'),$grade).dgs_catalog_select('academy_day','روز برگزاری',array(''=>'همه روزها')+dgs_catalog_day_names(),$day).dgs_catalog_select('academy_subject','درس / موضوع',$subjects,$subject).'<button class="dg-btn">'.dgs_portal_icon('search').' جست‌وجوی کلاس‌ها</button></form></section><section class="dc-card"><h2>'.dgs_portal_icon('timetable').' برنامه هفتگی کلی کلاس‌های تقویتی</h2>'.dgs_catalog_schedule($posts).'</section><div class="dc-section-head"><h2>'.dgs_portal_icon('classes').' لیست کلاس‌های فعال آموزشگاه</h2><span class="dc-tag">'.esc_html(dgs_fa_digits(count($posts))).' کلاس یافت شد</span></div><div class="dc-course-grid">';
 foreach($posts as $p){$teacher=dgs_catalog_teacher_post($p->ID);$name=dgs_catalog_teacher_name($p->ID);$cap=get_post_meta($p->ID,'_dgs_capacity',true);$days=dgs_catalog_days($p->ID);$daynames=dgs_catalog_day_names();$g=dgs_catalog_grade(get_post_meta($p->ID,'_dgs_grade',true));$out.='<article class="dc-course-card"><header><div class="dc-course-avatar">'.($teacher?dgs_avatar($teacher,'thumbnail'):dgs_portal_icon('users')).'</div><div><span class="dc-tag">'.esc_html(get_post_meta($p->ID,'_dgs_subject',true)?:'کلاس تقویتی').'</span><h3>'.esc_html($p->post_title).'</h3><p>'.($name?'استاد '.esc_html($name):'مدرس هنوز اعلام نشده است.').'</p></div></header><ul><li>'.dgs_portal_icon('classes').' پایه: '.esc_html($g?dgs_edu_grade_label($g):get_post_meta($p->ID,'_dgs_grade',true)).'</li><li>'.dgs_portal_icon('timetable').' روز برگزاری: '.esc_html($days?implode('، ',array_map(function($d)use($daynames){return $daynames[$d];},$days)):'طبق برنامه کلاس').'</li><li>'.dgs_portal_icon('timetable').' '.esc_html(get_post_meta($p->ID,'_dgs_schedule',true)?:'زمان اعلام می‌شود').'</li><li>'.dgs_portal_icon('users').' ظرفیت اعلام‌شده: '.esc_html($cap!==''?dgs_fa_digits($cap).' نفر':'اعلام می‌شود').'</li></ul><a class="dg-btn" href="'.esc_url(add_query_arg('academy_id',$p->ID,dgs_public_url('class'))).'">'.dgs_portal_icon('edit').' پیش‌ثبت‌نام کلاس</a></article>';}
 if(!$posts)$out.=dgs_empty('کلاسی با این مشخصات منتشر نشده است.');return $out.'</div></div>';
}
function dgs_catalog_news(){
 $tab=dgs_catalog_get('news_tab','school');if(!in_array($tab,array('school','ministry'),true))$tab='school';$root=get_category_by_slug($tab==='school'?'school-news':'ministry-news');$allowed=$root?array_merge(array($root->term_id),get_term_children($root->term_id,'category')):array();$category=absint(dgs_catalog_get('news_category'));if(!in_array($category,array_map('intval',$allowed),true))$category=0;$period=dgs_catalog_get('news_period');$search=dgs_catalog_get('news_search');$page=max(1,min(1000,absint(dgs_catalog_get('news_page','1'))));
 $args=array('post_type'=>'post','post_status'=>'publish','posts_per_page'=>4,'paged'=>$page,'s'=>$search,'ignore_sticky_posts'=>true);if($root)$args['cat']=$category?:$root->term_id;else $args['post__in']=array(0);if(in_array($period,array('7','30','365'),true))$args['date_query']=array(array('after'=>wp_date('Y-m-d',time()-(int)$period*DAY_IN_SECONDS),'inclusive'=>true));$q=new WP_Query($args);$categories=array(''=>'همه دسته‌بندی‌ها');foreach($allowed as $id){$term=get_term($id,'category');if($term&&!is_wp_error($term))$categories[$id]=$term->name;}
 $out='<div class="dc-page dc-news">'.dgs_catalog_heading('اخبار و اطلاعیه‌ها','جدیدترین اخبار، رویدادها و اطلاعیه‌های مدرسه دانشگران و آموزش و پرورش','requests').'<nav class="dc-news-tabs"><a '.($tab==='school'?'aria-current="page"':'').' href="'.esc_url(add_query_arg('news_tab','school',dgs_page_url('news'))).'">'.dgs_portal_icon('home').' اخبار مدرسه</a><a '.($tab==='ministry'?'aria-current="page"':'').' href="'.esc_url(add_query_arg('news_tab','ministry',dgs_page_url('news'))).'">'.dgs_portal_icon('education').' اطلاعیه‌های آموزش و پرورش</a></nav><form class="dc-filter" method="get" action="'.esc_url(dgs_page_url('news')).'"><input type="hidden" name="news_tab" value="'.esc_attr($tab).'"><label>جست‌وجوی خبر<input name="news_search" value="'.esc_attr($search).'" placeholder="جست‌وجوی خبر در مدرسه دانشگران…" maxlength="100"></label>'.dgs_catalog_select('news_period','بازه زمانی',array(''=>'همه بازه‌های زمانی',7=>'هفت روز اخیر',30=>'ماه اخیر',365=>'سال اخیر'),$period).dgs_catalog_select('news_category','دسته‌بندی',$categories,$category).'<button class="dg-btn">'.dgs_portal_icon('search').' جست‌وجو</button></form><div class="dc-news-layout"><main><div class="dc-news-list">';
 foreach($q->posts as $p){$cats=get_the_category($p->ID);$cat=$cats?$cats[0]->name:'';$out.='<article class="dc-news-row">';if(has_post_thumbnail($p))$out.='<a class="dc-news-image" href="'.esc_url(get_permalink($p)).'">'.get_the_post_thumbnail($p,'medium_large',array('loading'=>'lazy')).'</a>';$out.='<div><span class="dc-tag">'.esc_html($cat).'</span><h2><a href="'.esc_url(get_permalink($p)).'">'.esc_html($p->post_title).'</a></h2><small>'.dgs_portal_icon('timetable').' '.esc_html(dgs_display_date(get_post_timestamp($p))).'</small><p>'.esc_html(wp_trim_words(wp_strip_all_tags($p->post_excerpt?:$p->post_content),35)).'</p><a class="dg-btn" href="'.esc_url(get_permalink($p)).'">ادامه مطلب '.dgs_portal_icon('arrow').'</a></div></article>';}
 if(!$q->posts)$out.=dgs_empty('خبری با این مشخصات منتشر نشده است.');$out.='</div>'.dgs_catalog_pagination($page,(int)$q->max_num_pages,'news_page',remove_query_arg('news_page')).'</main><aside>'; $pinargs=$args;unset($pinargs['paged']);$pinargs['posts_per_page']=1;$pinargs['post__in']=get_option('sticky_posts',array())?:array(0);$pinned=get_posts($pinargs);
 $out.='<section class="dc-card dc-important"><h2>'.dgs_portal_icon('warning').' اطلاعیه مهم و ویژه</h2>';if($pinned){$p=$pinned[0];$out.='<h3>'.esc_html($p->post_title).'</h3><p>'.esc_html(wp_trim_words(wp_strip_all_tags($p->post_excerpt?:$p->post_content),35)).'</p><a class="dg-btn" href="'.esc_url(get_permalink($p)).'">ادامه اطلاعیه '.dgs_portal_icon('arrow').'</a>';}else $out.='<p>اطلاعیه ویژه‌ای تعیین نشده است.</p>';$out.='</section><section class="dc-card"><h2>'.dgs_portal_icon('timetable').' رویدادهای پیش رو</h2>';
 $today=dgs_jalali_parts((int)wp_date('Y'),(int)wp_date('m'),(int)wp_date('d'));$today=sprintf('%04d-%02d-%02d',...$today);$events=get_posts(array('post_type'=>'post','post_status'=>'publish','numberposts'=>5,'meta_key'=>'_dgs_event_date','orderby'=>'meta_value','order'=>'ASC','meta_query'=>array(array('key'=>'_dgs_event_date','value'=>$today,'compare'=>'>='))));foreach($events as $p)$out.='<a class="dc-event" href="'.esc_url(get_permalink($p)).'"><b>'.esc_html(dgs_fa_digits(get_post_meta($p->ID,'_dgs_event_date',true))).'</b><span><strong>'.esc_html($p->post_title).'</strong><small>'.dgs_portal_icon('pin').esc_html(get_post_meta($p->ID,'_dgs_event_venue',true)).'</small></span></a>';if(!$events)$out.='<p>رویداد آینده‌ای ثبت نشده است.</p>';$out.='</section></aside></div></div>';return $out;
}
add_action('init',function(){add_shortcode('daneshgaran_teachers','dgs_teacher_directory');add_shortcode('daneshgaran_academy','dgs_catalog_academy');},30);
function dgs_catalog_active(){$p=get_option('dgs_pages',array());return (!empty($p['teachers'])&&is_page((int)$p['teachers']))||(!empty($p['academy'])&&is_page((int)$p['academy']))||is_singular('dgs_teacher')||is_home();}
add_filter('template_include',function($template){if(get_template()!=='daneshgaran')return $template;if(is_singular('dgs_teacher')||is_home())return DGS_PATH.'includes/public-catalog-template.php';return $template;},99);
add_filter('body_class',function($classes){if(dgs_catalog_active())$classes[]='dc-catalog-page';return $classes;});
add_action('wp_enqueue_scripts',function(){if(!dgs_catalog_active()&&!dgs_is_role_portal())return;wp_register_style('dgs-catalog',false,array(),DGS_VERSION);wp_enqueue_style('dgs-catalog');$css=file_get_contents(DGS_PATH.'assets/public-catalog.css');$css=str_replace('ACADEMY_IMAGE_URL',esc_url_raw(DGS_URL.'assets/academy-reference.jpg'),$css);wp_add_inline_style('dgs-catalog',$css);});
add_action('add_meta_boxes',function(){add_meta_box('dgs_event','رویداد مدرسه (برای نمایش رویدادهای پیش رو)',function($post){wp_nonce_field('dgs_event','dgs_event_nonce');foreach(array('_dgs_event_date'=>'تاریخ شمسی مانند 1405-09-20','_dgs_event_venue'=>'محل رویداد') as $key=>$label)echo '<p><label>'.esc_html($label).'<input name="'.$key.'" value="'.esc_attr(get_post_meta($post->ID,$key,true)).'" class="widefat"></label></p>';},'post','side');});
add_action('save_post_post',function($id){if(!isset($_POST['dgs_event_nonce'])||!is_string($_POST['dgs_event_nonce'])||!wp_verify_nonce(wp_unslash($_POST['dgs_event_nonce']),'dgs_event')||!current_user_can('edit_post',$id)||wp_is_post_revision($id)||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE))return;$date=isset($_POST['_dgs_event_date'])&&is_string($_POST['_dgs_event_date'])?dgs_edu_digits(wp_unslash($_POST['_dgs_event_date'])):'';if($date===''||(dgs_record_birth($date)&&preg_match('/^14\d{2}-\d{2}-\d{2}$/D',$date)))update_post_meta($id,'_dgs_event_date',$date);if(isset($_POST['_dgs_event_venue'])&&is_string($_POST['_dgs_event_venue']))update_post_meta($id,'_dgs_event_venue',sanitize_text_field(wp_unslash($_POST['_dgs_event_venue'])));});
// Refresh directory pages after linked content changes, once after all metadata is saved.
function dgs_catalog_invalidate($post_id=0){static $ids=array(),$scheduled=false;if($post_id)$ids[(int)$post_id]=true;if($scheduled)return;$scheduled=true;add_action('shutdown',function()use(&$ids){$pages=get_option('dgs_pages',array());foreach(array('teachers','academy','news') as $key)if(!empty($pages[$key]))$ids[(int)$pages[$key]]=true;foreach(array_keys($ids) as $id)if(get_post_type($id)==='dgs_class'){$profile=dgs_catalog_teacher_post($id);if($profile)$ids[$profile]=true;}foreach(array_keys($ids) as $id){clean_post_cache($id);if(function_exists('rocket_clean_post'))rocket_clean_post($id);}},100);}
foreach(array('dgs_teacher','dgs_class','post') as $dgs_catalog_type)add_action('save_post_'.$dgs_catalog_type,function($id){if(!wp_is_post_revision($id))dgs_catalog_invalidate($id);},99);
